"""Independent SOW check from raw data + schedule.csv. usage: verify.py client week schedule.csv [eval.json]"""
import sys, math, json
import pandas as pd
from datetime import timedelta
from zoneinfo import ZoneInfo
client, week, sp = sys.argv[1:4]
C = {
 'litware': dict(tz='Europe/London', g=20, oh=(7,21), qh={}, sla={'priority':(0.9,30),'standard':(0.8,30),'email':(0.8,300)},
                 floor={'priority':(2,7,21)}, eff=1.45, earliest={'email':9}, stamp='end',
                 tpl={'D8':[(9,17)],'L8':[(13,21)],'P6a':[(7,13)],'P6b':[(15,21)],'P4':[(10,14)],'S44':[(8,12),(16,20)]}),
 'northwind': dict(tz='America/Chicago', g=30, oh=(6,24), qh={'vip':(8,20)}, sla={'priority':(0.9,30),'standard':(0.8,20),'vip':(0.9,20)},
                 floor={'vip':(1,6,24)}, eff=1.57, earliest={}, stamp='start',
                 tpl={'E8':[(6,14)],'D8':[(9,17)],'L8':[(13,21)],'N8':[(16,24)],'P6a':[(7,13)],'P6b':[(15,21)],'P4':[(10,14)],'S44':[(8,12),(16,20)]}),
}[client]
z = ZoneInfo(C['tz']); G = timedelta(minutes=C['g']); gs = C['g']*60
def ec(a,n):
    if n<=a: return 1.0
    t=1.0; s=1.0
    for k in range(1,n): t*=a/k; s+=t
    t*=a/n; top=t*n/(n-a); return top/(s+top)
def req(v,aht,tg,sec):
    a=v*aht/gs
    if a<=0: return 0
    n=1
    while True:
        if n>a and 1-ec(a,n)*math.exp(-(n-a)*sec/aht)>=tg and a/n<=0.85: return n
        n+=1
df = pd.read_csv(f'/app/data/{client}/export_{week}.csv')
col = 'interval_end_local' if C['stamp']=='end' else 'interval_start_local'
t = pd.to_datetime(pd.to_datetime(df[col]).dt.strftime('%Y-%m-%d %H:%M')+df.utc_offset.str.strip(), format='%Y-%m-%d %H:%M%z', utc=True)
if C['stamp']=='end': t = t - G
df['t'] = t.dt.floor(f"{C['g']}min")
df = df.drop_duplicates(['queue','t'])
mon = pd.Timestamp(pd.Timestamp.fromisocalendar(int(week[:4]), int(week[6:]), 1)).tz_localize(C['tz'])
grid = pd.date_range(mon.tz_convert('UTC'), (mon.tz_localize(None)+pd.Timedelta(days=7)).tz_localize(C['tz']).tz_convert('UTC'), freq=G, inclusive='left')
def lh(ts): l=ts.astimezone(z); return l.hour+l.minute/60
def operating(q,ts):
    lo,hi=C['qh'].get(q,C['oh']); return lo<=lh(ts)<hi
R={}
for r in df.itertuples():
    if r.t not in grid: continue
    h=lh(r.t); lo,hi=C['oh']
    R[r.queue,r.t]= req(max(r.volume,0),r.aht_sec,*C['sla'][r.queue]) if lo<=h<hi else 0
Q=list(C['sla'])
for q in Q:
    for ts in grid: R.setdefault((q,ts),0)
s = pd.read_csv(sp)
for c in ('segment_start_utc','segment_end_utc','break_start_utc'): s[c]=pd.to_datetime(s[c],utc=True)
ag = pd.read_csv(f'/app/data/agents/{client}.csv'); ag={r.agent_id:(r.contract,set(r.skills.split(';'))) for r in ag.itertuples()}
gross={(q,ts):0 for q in Q for ts in grid}; brk=dict.fromkeys(gross,0)
for r in s.itertuples():
    for ts in grid:
        if r.segment_start_utc<=ts<r.segment_end_utc:
            gross[r.queue,ts]+=1
            if r.break_minutes and r.break_start_utc < ts+G and ts < r.break_start_utc+timedelta(minutes=int(r.break_minutes)): brk[r.queue,ts]+=1
V={}
def bad(k,msg=None):
    V[k]=V.get(k,0)+1
    if msg and V[k]<=3: print('  VIOL',k,msg)
# floors
for q,(n,lo,hi) in C['floor'].items():
    for ts in grid:
        if lo<=lh(ts)<hi and gross[q,ts]-brk[q,ts]<n: bad('floor',f'{q} {ts}')
# exceptions: email-before-start style
exc=set()
for (q,ts),rq in R.items():
    if rq>0 and operating(q,ts) and q in C['earliest'] and lh(ts)<C['earliest'][q]: exc.add((q,ts))
# per agent
for aid,g in s.groupby('agent_id'):
    con,sk=ag[aid]
    g=g.sort_values('segment_start_utc')
    hrs=((g.segment_end_utc-g.segment_start_utc).dt.total_seconds()/3600).sum()
    if hrs> (40 if con=='FT' else 24)+1e-9: bad('weekly_hours',aid)
    if any(q not in sk for q in g.queue): bad('skill',aid)
    if (g.segment_start_utc.values[1:]<g.segment_end_utc.values[:-1]).any(): bad('overlap',aid)
    g=g.assign(day=[x.astimezone(z).date() for x in g.segment_start_utc])
    days=sorted(set(g.day)); run=1
    for a,b in zip(days,days[1:]):
        run=run+1 if (b-a).days==1 else 1
        if run>5: bad('consec',aid)
    prev_end=None
    for d,sg in g.groupby('day'):
        st,en=sg.segment_start_utc.min(),sg.segment_end_utc.max()
        if prev_end is not None and st-prev_end<timedelta(hours=11): bad('rest',f'{aid} {d}')
        prev_end=en
        if len(sg)>1 and con!='PT': bad('split',aid)
        if sg.segment_end_utc.max().astimezone(z).date()!=d and sg.segment_end_utc.max().astimezone(z).hour!=0: bad('midnight',aid)
        segs=sorted((lh(a), lh(b) or 24) for a,b in zip(sg.segment_start_utc,sg.segment_end_utc))
        if sorted(segs) not in [sorted(map(tuple,v)) for v in C['tpl'].values()]: bad('template',f'{aid} {segs}')
        for q in sg.queue:
            if q in C['earliest'] and min(x[0] for x in segs)<C['earliest'][q]: bad('earliest',aid)
        length=((sg.segment_end_utc-sg.segment_start_utc).dt.total_seconds()/3600).sum()
        b=sg[sg.break_minutes>0]
        if length<6-1e-9:
            if len(b): bad('break_count',aid)
            continue
        if len(b)!=1 or int(b.break_minutes.iloc[0])!=20: bad('break_count',f'{aid} {d}'); continue
        bs=b.break_start_utc.iloc[0]; q=sg.queue.iloc[0]
        inseg=lambda x: any(a<=x and x+timedelta(minutes=20)<=e for a,e in zip(sg.segment_start_utc,sg.segment_end_utc))
        winI=[ts for ts in grid if st+timedelta(hours=2)<=ts<=st+timedelta(hours=5) and inseg(ts)]
        winX=[ts for ts in winI if ts<st+timedelta(hours=5)]
        slot=bs.floor(G)
        if not (st+timedelta(hours=2)<=bs<=st+timedelta(hours=5)): bad('break_window',f'{aid} {bs}')
        if bs+timedelta(minutes=20)>slot+G: bad('break_straddle',aid)
        for nm,win in (('surplus_incl',winI),('surplus_excl',winX)):
            if not win or slot not in win: bad(nm+'_out',f'{aid} {bs}'); continue
            sur={ts:gross[q,ts]-R[q,ts] for ts in win}
            if sur[slot]<max(sur.values()): bad(nm,f'{aid} {d} {bs}')
# attainment
att={}; under=0
for q in Q:
    met=tot=0
    for ts in grid:
        if not operating(q,ts) or (q,ts) in exc: continue
        tot+=1; net=gross[q,ts]-brk[q,ts]
        met+= net>=R[q,ts]; under+=max(0,R[q,ts]-net)*C['g']/60
    att[q]=met/tot
reqh=sum(R.values())*C['g']/60
sch=((s.segment_end_utc-s.segment_start_utc).dt.total_seconds()/3600).sum()
print(client,week,'intervals',len(grid),'att',{k:round(v,3) for k,v in att.items()},'sched',round(sch,1),'req',round(reqh,1),'ratio',round(sch/reqh,4),
      'cap_ok',sch<=C['eff']*reqh,'under',round(under,1),'agents',s.agent_id.nunique(),'exc',len(exc))
print('  violations',V or 'none', 'ALL_ATT_OK' if min(att.values())>=0.95 else 'ATT_FAIL')
if len(sys.argv)>4:
    e=json.load(open(sys.argv[4]))
    print('  eval sla diff', {q: round(e['sla'][q]-att[q],3) for q in Q}, 'exc match', ('exceptions' not in e) or set(e['exceptions'])=={f"{q} {ts.strftime('%Y-%m-%dT%H:%M:%SZ')}" for q,ts in exc})
